def op(s, key, vkey, F, q0):
    from scipy.optimize import least_squares
    (u, v) = (s[key]['u'], s[key][vkey])
    keep = np.arange(len(u))
    f = F(u, q0)
    if key == 'panel_a':
        for _ in range(8):
            err = np.linalg.norm(f @ fit(f[keep], v[keep]) - v, axis=1)
            keep = np.argsort(err)[:40]

    def res(q):
        f = F(u[keep], q)
        return (f @ fit(f, v[keep]) - v[keep]).ravel()
    for _ in range(3):
        q = least_squares(res, q0, bounds=([0.3, 0.3], [5.0, 6.0]), gtol=1e-12).x
        f = F(u, q)
        w = fit(f[keep], v[keep])
        err = np.linalg.norm(f @ w - v, axis=1)
        if key == 'panel_a':
            keep = np.flatnonzero(err < max(0.001, 4 * np.median(err)))
    return (lambda x: F(x, q) @ w, w)
